/// <summary>
/// MET logistics postal address table extension
/// </summary>
[ExtensionOf(tableStr(LogisticsPostalAddress))]
internal final class METLogisiticsPostalAddress_tbl_Extension
{
}

Method.Source:
/// <summary>
/// Table modified field
/// </summary>
/// <param name = "_fieldId">field num of table LogisticsPostalAddress</param>
public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(LogisticsPostalAddress, City):
        case fieldNum(LogisticsPostalAddress, Street):
        case fieldNum(LogisticsPostalAddress, State):
        case fieldNum(LogisticsPostalAddress, ZipCode):
            this.setMETVerified();
            break;
    }
}

/// <summary>
/// Set MetVerified status based on conditions
/// </summary>
private void setMETVerified()
{
    if (this.METVerified == NoYes::Yes)
    {
        if ((this.orig().City != this.City && this.City != '')
            || (this.orig().Street != this.Street && this.Street != '')
            || (this.orig().State != this.State && this.State != '')
            || (this.orig().ZipCode != this.ZipCode && this.ZipCode != ''))
        {
            this.METVerified = NoYes::No;

        }

        if (this.City == '' || this.Street == '' || this.State == '' || this.ZipCode == '')
        {
            this.METVerified = NoYes::No;
        }
    }
}
